        Quest("CH2-023",2,23,"Fistfights",category="The Dead Harpy Tavern",giver="Mastbo",location="The Dead Harpy Tavern",prerequisites="Chapter 2; speak to Mastbo at the Dead Harpy tavern.",summary="Pay Mastbo's entry fee at the Dead Harpy tavern and defeat four unarmed challengers.",walkthroughSteps=listOf("Speak with Mastbo, who organizes fistfights at the Dead Harpy tavern.","Pay the 100-gold entry wager.","Defeat Kurt Iron Fist, Graden Sledgehammer, Bram Savage, and Walgard Skullbreaker in unarmed fights.","Collect the reward after each victory, then speak to Mastbo after all four fights to obtain the final strength bonus."),reward="100 gold and 200 XP per win; +5 Strength and 300 XP after all four wins, per April 2026 guide.",warnings="This activity does not appear as a journal quest. https://rpgrussia.com/threads/kulachnye-boi.66840/",searchTags=listOf("fistfights","the dead harpy tavern","local quest giver in the dead harpy tavern")),
        Quest("CH2-024",2,24,"Saturas's Notes",category="Onar's Farm",giver="Lee",location="Onar's Farm",prerequisites="Chapter 2; speak with Lee about Saturas's missing notes.",summary="Recover Lee's chest of Saturas's notes from the former New Camp and deliver them to Saturas in Jharkendar.",walkthroughSteps=listOf("Complete Letter for Lee and speak to Lee at Onar's farm in Chapter 2.","Lee gives you a key to a chest in the Valley of Mines' former New Camp.","Enter the dangerous old camp, now occupied by the dragon; the chest is on a rise to the right of the dragon's lair.","Open the chest, take Saturas's notes and return to Lee.","Follow Lee's instructions to bring the notes to Saturas in Jharkendar."),reward="Deliver Saturas's notes to the intended recipient; experience reward not independently confirmed.",warnings="Do not sell or discard Saturas's notes before completing Lee's request.",searchTags=listOf("saturas's notes","onar's farm","local quest giver in onar's farm")),
